#include <iostream>
#include <string>
#include <vector>

long long read_and_solve_leaders() {
    int n;
    std::cin >> n;
    std::string breed;
    std::cin >> breed;
    std::vector<int> end(n);
    for (int i = 0; i < n; ++i) std::cin >> end[i];
    int first_g = n, first_h = n, last_g = -1, last_h = -1;
    for (int i = 0; i < n; ++i) {
        if (breed[i] == 'G') {
            if (first_g == n) first_g = i;
            last_g = i;
        } else {
            if (first_h == n) first_h = i;
            last_h = i;
        }
    }
    const bool covers_g = end[first_g] >= last_g + 1;
    const bool covers_h = end[first_h] >= last_h + 1;
    long long answer = 0;
    if (covers_g) {
        for (int h = 0; h < n; ++h) {
            if (breed[h] != 'H') continue;
            const bool owns_breed = h == first_h && covers_h;
            const bool contains_g = h <= first_g && end[h] >= first_g + 1;
            if (owns_breed || contains_g) ++answer;
        }
    }
    if (covers_h) {
        for (int g = 0; g < n; ++g) {
            if (breed[g] != 'G') continue;
            const bool owns_breed = g == first_g && covers_g;
            const bool contains_h = g <= first_h && end[g] >= first_h + 1;
            if (owns_breed || contains_h) ++answer;
        }
    }
    if (covers_g && covers_h) --answer;
    return answer;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::cout << read_and_solve_leaders() << '\n';
    return 0;
}
