#include <algorithm>
#include <climits>
#include <iostream>
#include <vector>

struct Conditioner {
    int first, last;
    long long cooling, cost;
};

long long read_and_solve_air() {
    int n, m;
    std::cin >> n >> m;
    std::vector<long long> required(101, 0);
    for (int i = 0; i < n; ++i) {
        int first, last;
        long long amount;
        std::cin >> first >> last >> amount;
        for (int stall = first; stall <= last; ++stall) required[stall] = amount;
    }
    std::vector<Conditioner> ac(m);
    for (int i = 0; i < m; ++i) {
        std::cin >> ac[i].first >> ac[i].last >> ac[i].cooling >> ac[i].cost;
    }
    long long best = LLONG_MAX;
    for (int mask = 0; mask < (1 << m); ++mask) {
        std::vector<long long> supplied(101, 0);
        long long cost = 0;
        for (int i = 0; i < m; ++i) {
            if (!(mask & (1 << i))) continue;
            cost += ac[i].cost;
            for (int stall = ac[i].first; stall <= ac[i].last; ++stall) {
                supplied[stall] += ac[i].cooling;
            }
        }
        bool feasible = true;
        for (int stall = 1; stall <= 100; ++stall) {
            if (supplied[stall] < required[stall]) {
                feasible = false;
                break;
            }
        }
        if (feasible) best = std::min(best, cost);
    }
    return best;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::cout << read_and_solve_air() << '\n';
    return 0;
}
