#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

std::vector<int> read_and_solve_moo() {
    int q;
    std::cin >> q;
    std::vector<int> answers;
    while (q--) {
        std::string s;
        std::cin >> s;
        int best = 1000000;
        const int length = static_cast<int>(s.size());
        for (int i = 0; i + 2 < length; ++i) {
            if (s[i + 1] != 'O') continue;
            const int flips = (s[i] == 'O') + (s[i + 2] == 'M');
            best = std::min(best, length - 3 + flips);
        }
        answers.push_back(best == 1000000 ? -1 : best);
    }
    return answers;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(NULL);
    const std::vector<int> answers = read_and_solve_moo();
    for (std::size_t i = 0; i < answers.size(); ++i) std::cout << answers[i] << '\n';
    return 0;
}
